-- request: GET /api/audit/snaps?select=id,t:post->>title,s:history->0->>title,h:history::text&limit=5
SELECT json_build_object('has_next', coalesce(bool_or(s4.__rn > $7), false), 'has_prev', false, 'first', (json_agg(s4.__key ORDER BY s4.__rn ASC) FILTER (WHERE s4.__rn <= $7))->0, 'last', (json_agg(s4.__key ORDER BY s4.__rn ASC) FILTER (WHERE s4.__rn <= $7))->-1, 'n', count(*) FILTER (WHERE s4.__rn <= $7), 'rows', coalesce(json_agg(s4.data ORDER BY s4.__rn ASC) FILTER (WHERE s4.__rn <= $7), '[]'::json)) AS data
FROM (
  SELECT json_build_object('id', t0."id", $2::text, ((CASE WHEN (t0."post")::text IS NULL THEN NULL ELSE json_build_object('id', (t0."post")."id", 'author_id', (t0."post")."author_id", 'title', (t0."post")."title", 'body', (t0."post")."body", 'published', (t0."post")."published") END)::jsonb ->> $1::text), $5::text, ((CASE WHEN t0."history" IS NULL THEN NULL ELSE (SELECT coalesce(json_agg(CASE WHEN ((t0."history")[e2.o])::text IS NULL THEN NULL ELSE json_build_object('id', ((t0."history")[e2.o])."id", 'author_id', ((t0."history")[e2.o])."author_id", 'title', ((t0."history")[e2.o])."title", 'body', ((t0."history")[e2.o])."body", 'published', ((t0."history")[e2.o])."published") END ORDER BY e2.o), '[]'::json) FROM (SELECT generate_subscripts(t0."history", 1) AS o) e2) END)::jsonb -> $3::int4 ->> $4::text), $6::text, to_json(((CASE WHEN t0."history" IS NULL THEN NULL ELSE (SELECT coalesce(json_agg(CASE WHEN ((t0."history")[e3.o])::text IS NULL THEN NULL ELSE json_build_object('id', ((t0."history")[e3.o])."id", 'author_id', ((t0."history")[e3.o])."author_id", 'title', ((t0."history")[e3.o])."title", 'body', ((t0."history")[e3.o])."body", 'published', ((t0."history")[e3.o])."published") END ORDER BY e3.o), '[]'::json) FROM (SELECT generate_subscripts(t0."history", 1) AS o) e3) END)::jsonb)::"pg_catalog"."text")) AS data, jsonb_build_array(t0."id") AS __key, row_number() OVER (ORDER BY t0."id" ASC) AS __rn
  FROM "audit"."snaps" t0
  ORDER BY t0."id" ASC
  LIMIT 6
) s4
-- args: ["title","t",0,"title","s","h",5]
